INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 24, 24001, 102301, 2, "アヤネ", 2, 0, 0, 0, "2030/12/17 14:59:59", 401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 24, 24002, 102301, 2, "アヤネ", 1, 0, 0, 2.21, "2030/12/17 14:59:59", 402);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 24, 24003, 102301, 2, "アヤネ", 2, 0, 0, 0, "2030/12/17 14:59:59", 403);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 24, 24004, 192201, 1, "アサヒ", 2, 0, 0, 1.99, "2030/12/17 14:59:59", 701);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 24, 24005, 192201, 2, "アサヒ", 1, 0, 0, 2.21, "2030/12/17 14:59:59", 702);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 24, 24006, 192201, 1, "アサヒ", 2, 0, 0, 3.33, "2030/12/17 14:59:59", 703);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 24, 24007, 192301, 2, "部員３", 2, 0, 0, 0, "2030/12/17 14:59:59", 801);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 24, 24008, 192301, 2, "部員３", 1, 0, 0, 2.68, "2030/12/17 14:59:59", 802);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 24, 24009, 192301, 2, "部員３", 2, 0, 0, 0, "2030/12/17 14:59:59", 803);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "やった！", 24, 24010, 192501, 1, "", 1, 0, 0, 0, "2030/12/17 14:59:59", 501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "勝ったよ！", 24, 24011, 192501, 1, "", 1, 0, 0, 0, "2030/12/17 14:59:59", 502);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい調子！", 24, 24012, 192501, 1, "", 1, 0, 0, 0, "2030/12/17 14:59:59", 503);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 24, 24013, 113501, 2, "ミサト", 6, 0, 0, 5.33, "2030/12/17 14:59:59", 111);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 24, 24014, 113501, 2, "ミサト", 1, 0, 0, 6.85, "2030/12/17 14:59:59", 112);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 24, 24015, 113501, 2, "ミサト", 1, 0, 0, 3, "2030/12/17 14:59:59", 113);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 24, 24016, 192401, 2, "ダイチ", 1, 0, 0, 6.11, "2030/12/17 14:59:59", 611);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 24, 24017, 192401, 2, "ダイチ", 1, 0, 0, 6.75, "2030/12/17 14:59:59", 612);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 24, 24018, 192401, 2, "ダイチ", 2, 0, 0, 0, "2030/12/17 14:59:59", 613);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 24, 24019, 113401, 1, "ハツネ", 2, 0, 0, 4.52, "2030/12/17 14:59:59", 211);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 24, 24020, 113401, 1, "ハツネ", 2, 0, 0, 3.89, "2030/12/17 14:59:59", 212);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 24, 24021, 113401, 2, "ハツネ", 1, 0, 0, 13.49, "2030/12/17 14:59:59", 213);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 24, 24022, 106501, 2, "カヤ", 1, 0, 0, 3.17, "2030/12/17 14:59:59", 311);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 24, 24023, 106501, 2, "カヤ", 1, 0, 0, 4.42, "2030/12/17 14:59:59", 312);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 24, 24024, 106501, 1, "カヤ", 6, 0, 0, 2.89, "2030/12/17 14:59:59", 313);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 24, 24025, 102301, 3, "アヤネ", 4, 0, 0, 3.71, "2030/12/17 14:59:59", 421);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 24, 24026, 192201, 1, "アサヒ", 2, 0, 0, 5.1, "2030/12/17 14:59:59", 721);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 24, 24027, 192301, 3, "部員３", 1, 0, 0, 4.34, "2030/12/17 14:59:59", 821);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい勝負だったよ\nまたやろうね", 24, 24028, 192501, 1, "", 1, 0, 0, 0, "2030/12/17 14:59:59", 521);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 24, 24029, 113501, 2, "ミサト", 1, -360, 0, 5.62, "2030/12/17 14:59:59", 101);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 24, 24030, 113501, 2, "ミサト", 1, -360, 0, 9.58, "2030/12/17 14:59:59", 102);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 24, 24031, 113501, 2, "ミサト", 2, -360, 0, 0, "2030/12/17 14:59:59", 103);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 24, 24032, 113501, 1, "ミサト", 2, -360, 0, 9.13, "2030/12/17 14:59:59", 104);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, "2020/07/31 12:00:00", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 24, 24033, 113501, 2, "ミサト", 1, -360, 0, 8.27, "2030/12/17 14:59:59", 105);
